const fs=require('fs'),crypto=require('crypto');const p='papers/30-three-disk-nonconstant-roof-determinant/',n=p+'notes/';const sha=b=>crypto.createHash('sha256').update(b).digest('hex');const desc=f=>{const b=fs.readFileSync(f);return {path:f,bytes:b.length,sha256:sha(b)}};const E=JSON.parse(fs.readFileSync(n+'stage4_5_round4_recovery1_e6_continuous_review.json')),R=JSON.parse(fs.readFileSync(n+'stage4_5_round4_recovery1_integrity_report_draft.json')),F=JSON.parse(fs.readFileSync(n+'stage4_5_round4_recovery1_claim_strength_drift_findings.json')),C=JSON.parse(fs.readFileSync(n+'stage4_5_round4_claim_registry.json'));const problems=[];const cache=new Map();function blocks(f){if(cache.has(f))return cache.get(f);const t=fs.readFileSync(f,'utf8'),a=[...t.matchAll(/<!--block:(B[0-9]+)-->/g)],o={};for(let i=0;i<a.length;i++)o[a[i][1]]=t.slice(a[i].index+a[i][0].length,i+1<a.length?a[i+1].index:t.length).replace(/^\r?\n/,'').trimEnd();cache.set(f,o);return o;}
for(const row of E.operations){const patch=JSON.parse(fs.readFileSync(p+row.patch.path));const op=patch.ops[row.op_index];if(row.old_text!==blocks(p+row.pre_round_draft.path)[row.block_id])problems.push({type:'e6_old_text',round:row.revision_round,index:row.op_index});if(row.new_text!==op.new_text||row.block_id!==op.block_id||JSON.stringify(row.roadmap_item_ids)!==JSON.stringify(op.roadmap_item_ids))problems.push({type:'e6_patch',round:row.revision_round,index:row.op_index});}
const official=JSON.parse(fs.readFileSync(n+'stage4_5_round4_evidence_rows.json'));if(JSON.stringify(official)!==JSON.stringify(R.phases.E_claims.evidence_rows))problems.push({type:'report_evidence_copy'});const claims=new Map(C.claims.map(x=>[x.claim_id,x])),counts={};for(const row of official){counts[row.verdict]=(counts[row.verdict]||0)+1;const c=claims.get(row.claim.claim_id);if(!c||c.claim_text!==row.claim.text)problems.push({type:'registry_row_text',id:row.claim.claim_id});}
if(R.phases.E_claims.checked!==new Set(official.map(r=>r.claim.claim_id)).size||R.phases.E_claims.verified!==counts.VERIFIED)problems.push({type:'claim_summary'});if(R.phases.E_claims.claim_strength_drift_findings.artifact_sha256!==desc(n+'stage4_5_round4_recovery1_claim_strength_drift_findings.json').sha256)problems.push({type:'finding_pointer'});if(F.final_draft_sha256!==desc(p+'notes/stage4_prime_revision_round5.tex').sha256||F.revision_evidence_bundle_sha256!==desc(p+'notes/stage4_prime_revision_evidence_bundle_round5.json').sha256)problems.push({type:'finding_input_binding'});
const receipt=JSON.parse(fs.readFileSync('BATCH_ROUND10_STAGE4_5_ROUND4_RECOVERY1_RESUMPTION_RECEIPT.json'));const preserved=receipt.preservation.new_artifact_inventory.filter(x=>x.path.startsWith(p));for(const x of preserved){const a=desc(x.path);if(a.bytes!==x.bytes||a.sha256!==x.sha256)problems.push({type:'preserved_p30_input',expected:x,actual:a});}
console.log(JSON.stringify({observed_at_utc:new Date().toISOString(),check_kind:'NON_OFFICIAL_LOCAL_READ_ONLY_CONSISTENCY_AND_PRESERVATION',e6_rows_checked:E.operations.length,e6_rounds:E.round_authority_inventory.length,evidence_rows_exact_copy:JSON.stringify(official)===JSON.stringify(R.phases.E_claims.evidence_rows),claim_counts:counts,preserved_p30_pre_pause_files_checked:preserved.length,new_files:['stage4_5_round4_recovery1_e6_continuous_review.json','stage4_5_round4_recovery1_claim_strength_drift_findings.json','stage4_5_round4_recovery1_originality_revision_coverage.json','stage4_5_round4_recovery1_integrity_report_draft.json','stage4_5_round4_recovery1_compliance_report_draft.json'].map(x=>desc(n+x)),problems,status:problems.length?'FAIL':'PASS',scope:'Not an official Schema5/12/evidence replay or scientific validity check. Successful pre-pause official checks were not repeated.'},null,2));if(problems.length)process.exitCode=2;
NODE

